(function(){
  window.VN_LEARNING=window.VN_LEARNING||{};
  const M=(id,title,highYield,teaching,keyPoints,visual,mnemonic,goodToKnow,practiceConnection,activity)=>({id,title,highYield,teaching,keyPoints,visual,mnemonic,goodToKnow,practiceConnection,activity});
  const V=(title,kind,items)=>({title,kind,items}); const N=(title,cue,explanation)=>({title,cue,explanation}); const A=(prompt,options)=>({prompt,options}); const O=(text,correct,feedback)=>({text,correct,feedback});
  window.VN_LEARNING['lesson-4']={version:2,title:'Carbohydrates',chapter:'Whole plant foods, fibre + phytochemicals',duration:'95–115 minutes',
    outcomes:['Differentiate carbohydrate amount from carbohydrate quality and food structure.','Identify whole-grain foods using ingredient and product context rather than package colour.','Explain nutrient density without treating calories as the only measure of value.','Describe carotenoids, anthocyanins and other phytochemicals without supplement-style promises.','Correct outdated serving statistics, detox claims and malformed terminology in the source questions.'],
    modules:[
      {id:'quality',title:'See carbohydrate as a food matrix',summary:'Distinguish intact carbohydrate foods from refined and free-sugar sources.',moments:[
        M('vn4-m1','Carbohydrate quality is more than grams','Fibre, food structure, processing and meal context shape the metabolic effect of carbohydrate-rich foods.',[
          'Carbohydrates include sugars, starches and fibre. Beans, intact grains, vegetables, fruit and milk can all contain carbohydrate, yet their digestion and nutrient packages differ. Fibre and intact cell structures can slow eating and absorption, while refining and juicing remove or disrupt structure.',
          'A vegetarian diet can be high in protective whole-food carbohydrates or dominated by refined bread, sweets and sugary drinks. The useful question is not “Are carbs good or bad?” but “What is the source, form, portion and role in the meal?”'
        ],['Carbohydrate foods are heterogeneous.','Fibre and food structure matter.','Vegetarian status does not guarantee carbohydrate quality.'],
        V('Carbohydrate spectrum','comparison',[{label:'Intact',detail:'Beans, kernels, whole fruit and minimally processed vegetables.'},{label:'Processed but useful',detail:'Rolled oats, whole-grain bread and canned beans.'},{label:'Refined/free sugar',detail:'Sugary drinks, candy and low-fibre refined grains.'}]),
        N('Four quality questions','SOURCE · STRUCTURE · SERVING · SETTING', 'Identify the food, its structure, the amount and the meal context.'),
        'Processing is not automatically harmful; freezing, canning, cooking and grinding can improve access and convenience.',
        'For glycemic concerns, assess the whole meal and individual response rather than banning a food category.',
        A('Which feature most clearly distinguishes whole fruit from juice?',[O('Whole fruit contains no carbohydrate.',false,'Whole fruit contains natural sugars and other carbohydrates.'),O('Whole fruit retains more intact fibre structure.',true,'The matrix changes eating rate, satiety and absorption.'),O('Juice always contains added fat.',false,'That is not generally true.')])
        ),
        M('vn4-m2','Nutrient density needs context','Nutrient density describes nutrients relative to energy or serving, but energy-dense foods can still be nutritionally valuable.',[
          'A nutrient-dense food supplies substantial nutrients for its energy content. Many vegetables and fruits are rich in vitamins, minerals, fibre and phytochemicals while being low in energy. Yet nuts, seeds and avocado are energy dense and also provide valuable nutrients and unsaturated fats.',
          'The concept should help build adequacy, not label low-calorie foods as morally better. People with small appetites, growth needs or unintended weight loss may need both nutrient density and energy density.'
        ],['Nutrient density is not identical to low calorie.','Energy density can be useful.','Needs change with appetite and life stage.'],
        V('Two density axes','matrix',[{label:'High nutrient · low energy',detail:'Many non-starchy vegetables and fruits.'},{label:'High nutrient · high energy',detail:'Nuts, seeds and avocado.'},{label:'Lower nutrient · high energy',detail:'Many sweets and fried snack foods.'}]),
        N('Do not confuse the densities','NUTRIENTS / ENERGY', 'Nutrient density is a ratio, not a moral score.'),
        'Dark-green and orange vegetables are useful examples, but variety across colours and types matters more than one “best” vegetable.',
        'Match food density to the person’s goal: satiety, weight restoration, growth, athletic fueling or chronic-disease management.',
        A('Which food can be both energy dense and nutrient dense?',[O('Walnuts',true,'Walnuts provide energy, unsaturated fat, protein, minerals and ALA.'),O('Water',false,'Water is essential but does not provide substantial nutrients or energy.'),O('Hard candy',false,'It is energy dense but provides few nutrients.')])
        ),
        M('vn4-m9','Glycemic index is a tool—not a complete food score','Blood-glucose response depends on available carbohydrate, food structure, cooking, ripeness, meal composition and the person eating it.',[
          'Glycemic index compares the blood-glucose response to a standardized amount of available carbohydrate from a food eaten under test conditions. Glycemic load also considers the amount of available carbohydrate in a serving. Neither measure captures the full nutrient package, usual portion, satiety, preparation or what else is eaten. A food can have a moderate or high index and still contribute fibre, vitamins or minerals; another can have a lower value because it is high in fat yet offer little overall nutrition.',
          'Grinding and prolonged cooking can make starch more accessible, while intact kernels, viscous fibre, cooling-and-reheating effects on resistant starch, and pairing with protein or fat can modify the response. Individual glucose responses also vary. Use glycemic tools to refine a balanced plan, not to ban fruit, legumes or whole grains by a single number.'
        ],['Glycemic index standardizes carbohydrate amount, not usual serving size.','Glycemic load incorporates serving carbohydrate but still does not grade total nutrition.','Food form, preparation, meal composition and individual response matter.'],
        V('Glucose-response levers','systems',[{label:'Food',detail:'Starch type, fibre, ripeness and particle size.'},{label:'Kitchen',detail:'Cooking, cooling, grinding and processing.'},{label:'Meal',detail:'Portion plus protein, fat and other carbohydrate.'},{label:'Person',detail:'Metabolic health, activity, medication and individual variation.'}]),
        N('Never use one number alone','FOOD · KITCHEN · MEAL · PERSON', 'Interpret a glycemic value inside the real eating context.'),
        'A glycemic-index list cannot replace carbohydrate education, medication safety or glucose monitoring for someone with diabetes.',
        'Compare realistic portions and meal patterns; do not rank isolated foods as morally good or bad.',
        A('Why is glycemic index not a complete food-quality score?',[O('It ignores nutrient package, usual serving, meal context and individual response.',true,'Those dimensions can change the practical meaning of the number.'),O('It proves all whole grains have identical effects.',false,'Grains differ by variety and processing.'),O('It measures vitamin B12 content.',false,'It measures a glucose-response property, not B12.')])
        )
      ]},
      {id:'grains',title:'Use whole grains accurately',summary:'Read labels and recognize what whole grains do—and do not—provide.',moments:[
        M('vn4-m3','Whole grains retain bran, germ and endosperm','Keeping the grain’s three anatomical components preserves more fibre, minerals and phytochemicals than refining away the bran and germ.',[
          'The bran contains much of the fibre and several phytochemicals; the germ contributes fats, vitamins and minerals; the endosperm is primarily starch with some protein. Refining usually removes bran and germ, while enrichment returns selected nutrients but not the complete original matrix.',
          'Whole grains can contribute fibre, magnesium, zinc, plant sterols and other compounds. They are not natural sources of vitamin B12. Selenium content varies strongly with soil and origin, so exact values are not universal.'
        ],['Whole grain includes bran, germ and endosperm.','Enriched is not the same as whole.','Whole grains do not naturally supply B12.'],
        V('Grain kernel map','anatomy',[{label:'Bran',detail:'Fibre-rich outer layers.'},{label:'Germ',detail:'Embryo with fats and micronutrients.'},{label:'Endosperm',detail:'Starch and some protein.'}]),
        N('Three parts make it whole','B-G-E', 'Bran, Germ and Endosperm remain in their original proportions.'),
        'A multigrain product can contain several refined grains; “multigrain” does not prove whole grain.',
        'Use ingredient lists and jurisdiction-specific whole-grain labelling rather than judging by brown colour.',
        A('Which nutrient is not naturally supplied by whole grains?',[O('Fibre',false,'Whole grains can provide fibre.'),O('Magnesium',false,'Many whole grains contribute magnesium.'),O('Vitamin B12',true,'Natural B12 is not a characteristic whole-grain nutrient.')])
        ),
        M('vn4-m4','A label claim needs a full reading','The first ingredient can help identify a whole-grain product, but product names, flour terms and total grain composition still require context.',[
          'Look for explicit whole-grain ingredients such as whole oats, whole rye or whole-grain wheat. In some jurisdictions, “whole wheat flour” may not retain every original component in the same proportion, while “whole grain whole wheat” is more specific. Claims and rules vary by country.',
          'The ingredient list is ordered by weight before processing, but it does not show exact percentages unless provided. Fibre on the Nutrition Facts table, serving size, added sugars and sodium add useful context. A single “first ingredient” rule is a screening tool, not a complete product assessment.'
        ],['Prefer explicit whole-grain wording.','Labelling rules vary by jurisdiction.','Read fibre, serving size, sodium and sugars too.'],
        V('Label-reading sequence','sequence',[{label:'1 · Name',detail:'Ignore health halos such as “natural” or “multigrain.”'},{label:'2 · Ingredients',detail:'Find explicit whole-grain terms.'},{label:'3 · Facts',detail:'Check fibre, sodium, sugars and serving.'},{label:'4 · Fit',detail:'Decide how the product serves the meal.'}]),
        N('Read four layers','NAME → LIST → FACTS → FIT', 'Do not stop at the front of the package.'),
        'Dark colour can come from molasses, caramel or other ingredients and does not prove whole-grain content.',
        'Compare products that serve the same purpose rather than chasing one perfect food.',
        A('Which product gives the strongest whole-grain signal?',[O('“Wheat bread” with enriched wheat flour first.',false,'Wheat flour can be refined.'),O('Bread with whole-grain rye and whole oats listed first.',true,'The terms explicitly identify whole grains.'),O('Brown-coloured multigrain bread with no whole-grain ingredient.',false,'Colour and “multigrain” do not prove whole-grain composition.')])
        )
      ]},
      {id:'colour',title:'Connect colour with phytochemicals—carefully',summary:'Use food examples without promising that one pigment prevents disease.',moments:[
        M('vn4-m5','Pigments can signal phytochemical families','Carotenoids, anthocyanins and other compounds contribute colour and biological activity, but colour is a clue rather than a complete nutrient analysis.',[
          'Beta-carotene and other provitamin A carotenoids occur in many orange, yellow and dark-green vegetables. Lycopene contributes red colour to tomatoes, watermelon and pink grapefruit. Anthocyanins contribute red, blue and purple hues to berries, purple cabbage and other foods.',
          'Chlorophyll can visually mask orange carotenoids in green leaves, so a dark-green vegetable can still supply carotenoids. Food variety is more defensible than choosing one colour as uniquely protective.'
        ],['Orange/yellow/dark green can signal carotenoids.','Tomatoes are a major lycopene example.','Blue/purple foods often contain anthocyanins.'],
        V('Colour clues','palette',[{label:'Orange/yellow',detail:'Carotenoids such as beta-carotene.'},{label:'Red',detail:'Lycopene in tomatoes and selected fruits.'},{label:'Blue/purple',detail:'Anthocyanins in berries and purple vegetables.'},{label:'Dark green',detail:'Chlorophyll plus masked carotenoids.'}]),
        N('The correct blueberry term','ANTHOCYANINS, not “anthropene”', 'The source test contains a malformed term; preserve it as an error and learn the correct pigment family.'),
        'Pigment content varies by cultivar, ripeness, storage and preparation.',
        'Encourage colour variety as a practical strategy, not a promise that one “superfood” neutralizes disease.',
        A('Which compound family gives many blueberries their blue-purple colour?',[O('Anthocyanins',true,'These flavonoid pigments create red, blue and purple colours.'),O('Anthropene',false,'That is not the correct term; it appears to be a source error.'),O('Vitamin B12',false,'B12 is not a plant pigment.')])
        ),
        M('vn4-m6','Phytochemicals are not miniature medicines','Food phytochemicals may influence signalling, enzymes and oxidative processes, but isolated mechanisms do not prove a clinical outcome.',[
          'Phytochemicals include thousands of non-nutrient plant compounds. Some influence enzyme systems, cell signalling, inflammation or hormone receptors in laboratory models. Human effects depend on dose, metabolism, food matrix and the outcome studied.',
          'Phytoestrogens such as isoflavones have far weaker and more selective activity than endogenous estradiol; calling them “stronger estrogen” is incorrect. Food-based soy intake is not equivalent to high-dose isolated supplements, and disease claims require human outcome evidence.'
        ],['Mechanistic activity is not the same as clinical benefit.','Food matrix and dose matter.','Phytoestrogens are weaker/selective, not stronger than estradiol.'],
        V('Evidence bridge','bridge',[{label:'Compound',detail:'Identified in a plant food.'},{label:'Mechanism',detail:'Effect observed in cells or metabolism.'},{label:'Human exposure',detail:'Absorption, dose and food matrix.'},{label:'Outcome',detail:'Clinical effect tested in people.'}]),
        N('Do not jump the bridge','COMPOUND → MECHANISM → HUMAN → OUTCOME', 'Each step needs evidence; a test-tube effect is not a disease cure.'),
        'Antioxidant activity measured in a test tube does not translate directly into an “antioxidant score” inside the body.',
        'Use food-first examples and avoid recommending isolated phytochemical supplements for unproven prevention claims.',
        A('Which statement is accurate about phytoestrogens?',[O('They are universally stronger than human estrogen.',false,'Their activity is generally much weaker and selective.'),O('Their health effects depend on compound, dose, tissue and evidence type.',true,'Context determines biological and clinical meaning.'),O('They guarantee prevention of hormone-dependent cancer.',false,'No food compound guarantees prevention.')])
        )
      ]},
      {id:'claims',title:'Evaluate antioxidant and detox language',summary:'Replace dated statistics and vague detox claims with testable mechanisms.',moments:[
        M('vn4-m7','Free radicals are part of normal biology','Reactive species arise from normal metabolism and external exposures; the goal is regulation, not complete elimination.',[
          'Reactive oxygen species form during normal mitochondrial metabolism and immune defence, and exposure can increase with radiation, smoking, pollution or intense exercise. Cells use antioxidant enzymes and dietary-derived compounds to regulate oxidative balance.',
          'The body does not need every free radical “quenched,” and a food’s laboratory antioxidant capacity does not predict a clinical effect. Regular fruits, vegetables, legumes, nuts and whole grains support a broad nutrient pattern without requiring detox rhetoric.'
        ],['Reactive species have normal biological roles.','Oxidative stress reflects imbalance, not the mere presence of radicals.','Food patterns matter more than a single antioxidant score.'],
        V('Oxidative balance','balance',[{label:'Formation',detail:'Metabolism, immunity and exposures produce reactive species.'},{label:'Defence',detail:'Endogenous enzymes and dietary factors support regulation.'},{label:'Imbalance',detail:'Excess formation or inadequate defence can damage molecules.'}]),
        N('Balance, not zero','FORM · DEFEND · BALANCE', 'The goal is regulated redox biology, not eliminating every reactive molecule.'),
        '“Tropical fruits” is not a scientific category of free-radical causation; the source item is malformed.',
        'Challenge detox claims by asking which compound, pathway, dose and human outcome were demonstrated.',
        A('Which statement best describes free radicals?',[O('They should all be eliminated.',false,'Some reactive species have signalling and immune roles.'),O('They arise in normal biology, and harm can occur when regulation is overwhelmed.',true,'This describes oxidative balance.'),O('Only tropical fruit creates them.',false,'That source option is nonsensical.')])
        ),
        M('vn4-m8','Cytochrome P450 is a metabolic system, not a cleanse','Cytochrome P450 enzymes transform many drugs and compounds; metabolism can promote elimination or create reactive intermediates.',[
          'Cytochrome P450 enzymes are prominent in the liver and other tissues. They oxidize many medications, environmental compounds and endogenous molecules. Transformation may make a compound easier to conjugate and excrete, but it can also activate a procarcinogen or generate a reactive metabolite.',
          'Therefore “detoxifies and eliminates carcinogens” is incomplete. The system is better understood as biotransformation, followed by additional metabolism and excretion pathways. Food interactions with these enzymes can also alter medication levels.'
        ],['P450 enzymes perform biotransformation.','Metabolism can detoxify or bioactivate.','Food-drug interactions can be clinically important.'],
        V('Biotransformation fork','flow',[{label:'Compound',detail:'Drug, endogenous molecule or environmental chemical.'},{label:'P450 reaction',detail:'Oxidation changes the molecule.'},{label:'Safer route',detail:'Conjugation and excretion may follow.'},{label:'Reactive route',detail:'Some products can be more biologically active.'}]),
        N('Metabolism has two directions','DETOX or BIOACTIVATE', 'Do not assume every metabolic reaction makes a compound harmless.'),
        'Grapefruit-food interactions are a familiar example of diet affecting drug-metabolizing enzymes, though the exact mechanism varies by compound.',
        'Do not advise “detox” products to someone taking medication; refer potential interactions to a pharmacist or prescriber.',
        A('What is the most accurate description of cytochrome P450?',[O('It only eliminates carcinogens.',false,'Some reactions bioactivate compounds.'),O('It biotransforms many compounds, sometimes supporting elimination and sometimes creating active intermediates.',true,'This captures both possible directions.'),O('It is a phytochemical found only in blueberries.',false,'It is an enzyme superfamily in the body.')])
        ),
        M('vn4-m10','Food-first phytochemicals are not the same as concentrated supplements','A varied plant-food pattern supplies compounds in a food matrix; isolated high doses can behave differently and can interact with treatment.',[
          'Fruits, vegetables, legumes, whole grains, nuts, seeds, herbs and spices deliver phytochemicals alongside fibre and essential nutrients. That exposure is not equivalent to extracting one compound into a high-dose capsule. Dose-response can be nonlinear, metabolites may differ among people, and a compound with antioxidant behaviour in one setting may have other actions in another.',
          'Concentrated products can change drug absorption or metabolism, affect bleeding risk or be inappropriate during cancer therapy. Beta-carotene supplement trials in high-risk smokers are a classic warning that a plausible antioxidant mechanism does not guarantee benefit. The defensible approach is food variety, evidence-based treatment and medication/supplement review with a pharmacist or clinician.'
        ],['Food matrix and supplement dose are different exposures.','Mechanism alone cannot establish benefit or safety.','Medication and treatment interactions require qualified review.'],
        V('Food-to-pill evidence gap','comparison',[{label:'Whole food',detail:'Complex matrix, usual culinary dose and multiple nutrients.'},{label:'Extract',detail:'Concentrated single or limited compounds.'},{label:'Interaction',detail:'Absorption, enzymes, bleeding and treatment effects may change.'},{label:'Decision',detail:'Require human benefit and safety evidence for the intended use.'}]),
        N('Do not shrink a diet into a capsule','MATRIX · DOSE · INTERACTION · OUTCOME', 'Check all four before treating a supplement like its source food.'),
        'NCI cautions that laboratory and animal findings on dietary components often do not establish cancer prevention in people; human outcomes and study design matter.',
        'Ask specifically about powders, extracts, teas and “detox” kits during medication reconciliation—people may not call them supplements.',
        A('Why can a high-dose phytochemical supplement differ from eating its source food?',[O('The dose, matrix, metabolism and interaction profile can all change.',true,'The supplement is a different exposure.'),O('Whole foods contain no bioactive compounds.',false,'They contain many, within a complex matrix.'),O('Every antioxidant supplement prevents cancer.',false,'Clinical evidence does not support that universal claim.')])
        )
      ]}
    ],
    sources:[
      {title:'Health Canada — Canada’s Dietary Guidelines',url:'https://www.canada.ca/en/health-canada/services/food-guide/explore/dietary-guidelines/section-1-foundation-healthy-eating.html'},
      {title:'National Cancer Institute — Diet and Cancer Risk',url:'https://www.cancer.gov/about-cancer/causes-prevention/risk/diet'},
      {title:'NCCIH — Detoxes and Cleanses: What You Need To Know',url:'https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know'},
      {title:'National Academies — Dietary Reference Intakes for Energy, Carbohydrate and Fiber',url:'https://nap.nationalacademies.org/catalog/10490/dietary-reference-intakes-for-energy-carbohydrate-fiber-fat-fatty-acids-cholesterol-protein-and-amino-acids'}
    ],
    caseStudy:{title:'The blueberry “detox” post',scenario:'A client shares a post claiming that blueberry “anthropene” neutralizes every free radical and activates a liver detox switch that prevents cancer.',prompts:['Which term is incorrect?','Where does the claim jump from mechanism to outcome?','How would you preserve enthusiasm for berries while correcting the science?'],takeaway:'Blueberries can be part of a nutrient-dense pattern, but the correct pigment is anthocyanin and neither antioxidant activity nor P450 metabolism guarantees cancer prevention.'},
    recap:['Carbohydrate quality depends on source, structure and context.','Nutrient density is not simply low calorie.','Glycemic index and load are tools, not complete food-quality scores.','Whole grains retain bran, germ and endosperm.','Colour can signal phytochemical families but not guarantee an outcome.','Anthocyanins—not “anthropene”—colour many berries.','P450 enzymes can detoxify or bioactivate compounds.','A high-dose phytochemical supplement is not equivalent to its source food.'],
    flashcards:[{front:'Three whole-grain parts',back:'Bran, germ and endosperm.',tag:'grains'},{front:'Enriched grain',back:'A refined grain with selected nutrients restored; not equivalent to the original whole grain.',tag:'grains'},{front:'Whole-grain B12',back:'Whole grains are not natural vitamin B12 sources.',tag:'grains'},{front:'Nutrient density',back:'Nutrients relative to energy or serving; it does not mean “lowest calorie.”',tag:'quality'},{front:'Carbohydrate quality',back:'Source, structure, processing, fibre, portion and meal context.',tag:'quality'},{front:'Glycemic index',back:'Response to a standardized amount of available carbohydrate; not a full nutrient or serving-size score.',tag:'glycemia'},{front:'Glycemic load',back:'A measure that incorporates the available carbohydrate in a serving, but still omits the full food and meal context.',tag:'glycemia'},{front:'Lycopene food',back:'Tomatoes are a major example.',tag:'colour'},{front:'Anthocyanins',back:'Red-blue-purple flavonoid pigments in berries and many purple plant foods.',tag:'colour'},{front:'“Anthropene”',back:'A malformed source term; the intended blueberry pigment family is anthocyanins.',tag:'correction'},{front:'Phytoestrogen',back:'Plant compound with weak/selective estrogen-receptor activity; not stronger than estradiol as a blanket rule.',tag:'phytochemicals'},{front:'Food versus extract',back:'Matrix, dose, metabolism and interaction profile can all change when a compound is concentrated.',tag:'supplements'},{front:'Oxidative stress',back:'An imbalance between reactive-species formation and regulatory/defence capacity.',tag:'oxidation'},{front:'Cytochrome P450',back:'An enzyme superfamily that biotransforms drugs and other compounds.',tag:'metabolism'},{front:'Bioactivation',back:'Metabolism that turns a precursor into a more biologically active or reactive compound.',tag:'metabolism'}],
    practice:[{tag:'quality',prompt:'Give one intact and one refined carbohydrate-food example.',answer:'Examples: intact barley versus white bread, or whole fruit versus juice.',rationale:'Structure changes the food matrix.'},{tag:'density',prompt:'Why can nuts be both energy dense and nutrient dense?',answer:'They provide substantial energy plus protein, unsaturated fat, fibre, vitamins and minerals.',rationale:'The two density concepts are different.'},{tag:'glycemia',prompt:'Why is glycemic index not a complete food score?',answer:'It does not fully capture usual serving, nutrient package, preparation, meal pairing or individual response.',rationale:'A standardized response needs real-world context.'},{tag:'glycemia',prompt:'Name four levers that can change glucose response.',answer:'Food structure/ripeness, preparation, portion/meal composition and the person’s metabolic or medication context.',rationale:'Response is not determined by one label.'},{tag:'grains',prompt:'Name the three parts retained in a whole grain.',answer:'Bran, germ and endosperm.',rationale:'Their retention defines whole-grain structure.'},{tag:'labels',prompt:'Why is “multigrain” insufficient proof of whole grain?',answer:'It means multiple grain types, which may all be refined.',rationale:'Explicit whole-grain ingredients are needed.'},{tag:'colour',prompt:'Which pigment family is the source test likely trying to name for blueberries?',answer:'Anthocyanins.',rationale:'“Anthropene” is not the correct term.'},{tag:'phytochemicals',prompt:'Why does a cell-study mechanism not prove disease prevention?',answer:'Human absorption, dose, metabolism, food matrix and clinical outcomes still need testing.',rationale:'Mechanism is only one evidence step.'},{tag:'supplements',prompt:'Why is a concentrated extract not interchangeable with its source food?',answer:'The matrix, dose, metabolism and interaction profile differ.',rationale:'It is a different exposure.'},{tag:'oxidation',prompt:'Are all free radicals harmful?',answer:'No. Reactive species have normal signalling and immune roles; imbalance can cause damage.',rationale:'Redox biology is regulated rather than zero.'},{tag:'P450',prompt:'Give the two possible directions of P450 metabolism.',answer:'It may support detoxification/elimination or bioactivate a compound into a more reactive form.',rationale:'“Detox only” is incomplete.'},{tag:'evidence',prompt:'How should an old fixed cancer-risk percentage be handled?',answer:'Preserve the source, identify the population and date, and avoid treating it as a timeless individual prediction.',rationale:'Risk estimates are context dependent.'},{tag:'teach-back',prompt:'Summarize the lesson in one line.',answer:'Choose varied, fibre-rich carbohydrate foods and evaluate phytochemical claims across the full evidence bridge.',rationale:'This integrates food quality and evidence literacy.'}]
  };
})();

/* Lesson 4 reading integration: append-only learning IDs preserve existing progress. */
(function(){const l=window.VN_LEARNING["lesson-4"]; Object.assign(l,{"version":3,"sourceLabel":"BV 2003 chapters 5–6 inspected · Dietitian’s Guide edition-matched support","sourceCoverage":"Full assigned Dietitian’s Guide fourth-edition chapters unavailable; topic-matched third-edition support only. No graded Lesson 4 key supplied."}); l.modules.push({"id":"reading-application","title":"Apply the assigned readings","summary":"Source-aware review: grain quality, fibre properties, produce nutrients and serving-based glycemia.","moments":[{"id":"vn4-m11","title":"Match the reading to the edition","highYield":"Chapter numbers are not interchangeable across editions.","teaching":["The supplied Becoming Vegetarian, revised 2003, was inspected directly: chapter 5, Energy Plus, printed pages 151–174, covers grains; chapter 6, Perfect Protectors, pages 175–196, covers vegetables and fruits. The teaching here summarizes those readings in original words.","The assigned fourth-edition Dietitian’s Guide has chapter 5 Carbohydrates (new) and chapter 9 Non-Nutrient Compounds in Plant Foods (expanded from third-edition chapter 8). The available PDF is actually the third edition (2011): its chapter 5 is Calcium and chapter 9 Soyfoods. Third-edition chapter 8 Phytochemicals supplies topic-matched supporting material, not a complete substitute for the assigned fourth-edition chapters. Full fourth-edition text and a graded Lesson 4 answer key have not been supplied."],"keyPoints":["Check title + edition + chapter title.","This is a reading-based synthesis, not an official Lesson 4 answer key."],"visual":{"title":"Match the reading to the edition","kind":"comparison","items":[{"label":"Becoming Vegetarian 2003","detail":"Ch5 grains; ch6 vegetables and fruits—directly inspected."},{"label":"Dietitian’s Guide 4e assignment","detail":"Ch5 Carbohydrates; ch9 Non-Nutrient Compounds—publisher mapping verified."},{"label":"Available Dietitian’s Guide 3e","detail":"Ch8 Phytochemicals is topic-matched support; full assigned 4e text unavailable."}]},"mnemonic":{"title":"Remember","cue":"Check title + edition + chapter title.","explanation":"Chapter numbers are not interchangeable across editions."},"goodToKnow":"The assigned fourth-edition Dietitian’s Guide has chapter 5 Carbohydrates (new) and chapter 9 Non-Nutrient Compounds in Plant Foods (expanded from third-edition chapter 8). The available PDF is actually the third edition (2011): its chapter 5 is Calcium and chapter 9 Soyfoods. Third-edition chapter 8 Phytochemicals supplies topic-matched supporting material, not a complete substitute for the assigned fourth-edition chapters. Full fourth-edition text and a graded Lesson 4 answer key have not been supplied.","practiceConnection":"Explain the distinction first, then apply it to the food or label in the question.","activity":{"prompt":"Your PDF chapter 5 says Calcium. What should you do?","options":[{"text":"Check the edition and topic mapping before studying it as the carbohydrate assignment.","correct":true,"feedback":"Yes—apply the distinction taught above."},{"text":"Assume every edition has the same chapters.","correct":false,"feedback":"Review the key distinction, not just a familiar food name."},{"text":"Treat chapter 9 Soyfoods as the complete assigned Non-Nutrient Compounds chapter.","correct":false,"feedback":"Review the key distinction, not just a familiar food name."}]}},{"id":"vn4-m12","title":"Separate sugars, starch and fibre","highYield":"Chemical category alone does not determine a food’s nutritional value.","teaching":["Sugars are small carbohydrates, such as glucose, fructose and sucrose. Starch is made of longer glucose chains that digestive enzymes usually break down. Fibre includes carbohydrates that escape digestion in the small intestine; some are subsequently fermented in the colon. Resistant starch also escapes small-intestinal digestion.","Fruit contains simple sugars together with water, fibre and micronutrients. White bread contains complex starch but may be low in fibre. Therefore simple does not automatically mean unhealthy and complex does not automatically mean healthy. Use structure, portion and the whole nutrient package."],"keyPoints":["Classify the carbohydrate; then assess the food.","Sugars, starch and fibre can occur together."],"visual":{"title":"Separate sugars, starch and fibre","kind":"comparison","items":[{"label":"Sugars","detail":"Small units; naturally present in fruit and milk or added to foods."},{"label":"Starch","detail":"Long glucose chains; grains, potatoes and legumes."},{"label":"Fibre","detail":"Resists small-intestinal digestion; properties vary."}]},"mnemonic":{"title":"Remember","cue":"Classify the carbohydrate; then assess the food.","explanation":"Chemical category alone does not determine a food’s nutritional value."},"goodToKnow":"Fruit contains simple sugars together with water, fibre and micronutrients. White bread contains complex starch but may be low in fibre. Therefore simple does not automatically mean unhealthy and complex does not automatically mean healthy. Use structure, portion and the whole nutrient package.","practiceConnection":"Explain the distinction first, then apply it to the food or label in the question.","activity":{"prompt":"Why is white bread not automatically better than an apple because its carbohydrate is complex?","options":[{"text":"Chain length does not capture fibre, structure or micronutrients.","correct":true,"feedback":"Yes—apply the distinction taught above."},{"text":"Fruit has no carbohydrate.","correct":false,"feedback":"Review the key distinction, not just a familiar food name."},{"text":"Every complex carbohydrate is fibre.","correct":false,"feedback":"Review the key distinction, not just a familiar food name."}]}},{"id":"vn4-m13","title":"Match fibre properties to their functions","highYield":"Solubility, viscosity and fermentability describe different, overlapping properties.","teaching":["Insoluble fibre often contributes stool bulk and helps regularity. Viscous soluble fibres, such as oat beta-glucan, can slow nutrient absorption and help lower LDL cholesterol. Fermentable fibres are used by gut microbes and can yield short-chain fatty acids. Not every soluble fibre forms a gel, and not every insoluble fibre is nonfermentable.","Oats and barley supply beta-glucan; beans, fruit, vegetables and whole grains contribute mixtures of fibres. Prefer a variety rather than assigning each food one exclusive fibre type. Increase fibre gradually and drink adequate fluid to improve tolerance; individual digestive symptoms may need tailored advice."],"keyPoints":["Fibre categories overlap.","Bulk, viscosity and fermentation are different functions."],"visual":{"title":"Match fibre properties to their functions","kind":"comparison","items":[{"label":"Insoluble","detail":"Often contributes stool bulk."},{"label":"Viscous soluble","detail":"Can slow absorption and help lower LDL."},{"label":"Fermentable","detail":"Microbial use can produce short-chain fatty acids."}]},"mnemonic":{"title":"Remember","cue":"Fibre categories overlap.","explanation":"Solubility, viscosity and fermentability describe different, overlapping properties."},"goodToKnow":"Oats and barley supply beta-glucan; beans, fruit, vegetables and whole grains contribute mixtures of fibres. Prefer a variety rather than assigning each food one exclusive fibre type. Increase fibre gradually and drink adequate fluid to improve tolerance; individual digestive symptoms may need tailored advice.","practiceConnection":"Explain the distinction first, then apply it to the food or label in the question.","activity":{"prompt":"A fibre dissolves in water. Does that prove it forms a gel and is fully fermented?","options":[{"text":"No. Solubility, viscosity and fermentability are separate properties.","correct":true,"feedback":"Yes—apply the distinction taught above."},{"text":"Yes, all three terms mean exactly the same thing.","correct":false,"feedback":"Review the key distinction, not just a familiar food name."},{"text":"Yes, every soluble fibre has identical effects.","correct":false,"feedback":"Review the key distinction, not just a familiar food name."}]}},{"id":"vn4-m14","title":"Connect produce nutrients to functions","highYield":"Nutrient density means useful nutrients relative to energy—not simply few calories.","teaching":["Orange, yellow and dark-green vegetables often provide provitamin A carotenoids. Vitamin C supports collagen formation and improves nonheme iron absorption when eaten with iron-containing plant foods. Vitamin K supports normal blood clotting. Folate supports DNA synthesis and cell division. Produce can also contribute potassium and magnesium.","Build a varied plate: dark leafy greens, orange vegetables, berries, citrus and other produce contribute different combinations. Lutein and zeaxanthin occur in leafy greens; lycopene in tomatoes; anthocyanins in blueberries; glucosinolates in cruciferous vegetables; isoflavones in soy. Not every carotenoid converts to vitamin A, and no colour or compound guarantees disease prevention."],"keyPoints":["Link nutrient → function → food example.","Variety is stronger than a single superfood claim."],"visual":{"title":"Connect produce nutrients to functions","kind":"comparison","items":[{"label":"Vitamin C","detail":"Collagen; enhances plant-iron absorption."},{"label":"Folate","detail":"DNA synthesis and cell division."},{"label":"Vitamin K","detail":"Normal blood clotting."},{"label":"Provitamin A carotenoids","detail":"Some carotenoids can supply vitamin A."}]},"mnemonic":{"title":"Remember","cue":"Link nutrient → function → food example.","explanation":"Nutrient density means useful nutrients relative to energy—not simply few calories."},"goodToKnow":"Build a varied plate: dark leafy greens, orange vegetables, berries, citrus and other produce contribute different combinations. Lutein and zeaxanthin occur in leafy greens; lycopene in tomatoes; anthocyanins in blueberries; glucosinolates in cruciferous vegetables; isoflavones in soy. Not every carotenoid converts to vitamin A, and no colour or compound guarantees disease prevention.","practiceConnection":"Explain the distinction first, then apply it to the food or label in the question.","activity":{"prompt":"Why pair lentils with bell pepper or citrus?","options":[{"text":"Vitamin C can enhance absorption of nonheme iron.","correct":true,"feedback":"Yes—apply the distinction taught above."},{"text":"Vitamin C converts all lentil protein into B12.","correct":false,"feedback":"Review the key distinction, not just a familiar food name."},{"text":"Citrus removes every antinutrient.","correct":false,"feedback":"Review the key distinction, not just a familiar food name."}]}},{"id":"vn4-m15","title":"Apply glycemic load to a serving","highYield":"GI compares a standardized carbohydrate amount; GL also uses the available carbohydrate in the serving.","teaching":["For a worked example, glycemic load = GI × grams of available carbohydrate in a serving ÷ 100. A hypothetical food with GI 60 and 20 g available carbohydrate has GL 12. Doubling that serving to 40 g gives GL 24, even though the GI value has not changed.","This is a teaching example, not a prediction of an individual glucose reading. Actual responses vary with preparation, ripeness, meal composition and the person. Neither GI nor GL measures the full nutritional quality of a food or replaces personalized diabetes care."],"keyPoints":["GL = GI × serving available carbohydrate ÷ 100.","Portion affects GL without changing the GI value."],"visual":{"title":"Apply glycemic load to a serving","kind":"comparison","items":[{"label":"GI 60; carbohydrate 20 g","detail":"GL 12."},{"label":"GI 60; carbohydrate 40 g","detail":"GL 24."}]},"mnemonic":{"title":"Remember","cue":"GL = GI × serving available carbohydrate ÷ 100.","explanation":"GI compares a standardized carbohydrate amount; GL also uses the available carbohydrate in the serving."},"goodToKnow":"This is a teaching example, not a prediction of an individual glucose reading. Actual responses vary with preparation, ripeness, meal composition and the person. Neither GI nor GL measures the full nutritional quality of a food or replaces personalized diabetes care.","practiceConnection":"Explain the distinction first, then apply it to the food or label in the question.","activity":{"prompt":"What changes when the example serving doubles?","options":[{"text":"GL doubles from 12 to 24; GI stays 60.","correct":true,"feedback":"Yes—apply the distinction taught above."},{"text":"GI doubles to 120.","correct":false,"feedback":"Review the key distinction, not just a familiar food name."},{"text":"Neither quantity can change.","correct":false,"feedback":"Review the key distinction, not just a familiar food name."}]}}]}); l.practice.push(...[{"tag":"fibre application","prompt":"A cereal says soluble fibre. Can you infer that all of it forms a gel and is readily fermented?","answer":"No. Solubility, viscosity and fermentability are distinct, overlapping properties.","rationale":"Match each property to its function rather than treating all soluble fibre alike."},{"tag":"meal application","prompt":"Choose a produce addition to a lentil meal that can improve nonheme iron absorption, and explain why.","answer":"Bell pepper, citrus or another vitamin-C-rich food can enhance nonheme iron absorption.","rationale":"Connect the nutrient to a practical meal choice."},{"tag":"portion application","prompt":"A hypothetical food has GI 60 and 20 g available carbohydrate per serving. Calculate GL for one and two servings.","answer":"One: 60 × 20 ÷ 100 = 12. Two: 60 × 40 ÷ 100 = 24.","rationale":"GL incorporates portion carbohydrate; GI remains 60."}]); l.flashcards.push(...[{"front":"Fibre’s three properties","back":"Solubility, viscosity and fermentability overlap but are not interchangeable.","tag":"fibre"},{"front":"Vitamin C + plant iron","back":"Vitamin C can enhance nonheme iron absorption when included in the meal.","tag":"produce"},{"front":"Lesson 4 edition map","back":"BV 2003 ch5 grains/ch6 produce. Assigned Guide 4e ch5 carbohydrates/ch9 non-nutrient compounds; available Guide 3e ch8 is supporting phytochemical material only.","tag":"sources"}]); l.sources.push(...[{"title":"Publisher — Dietitian’s Guide fourth-edition transition guide (chapter mapping)","url":"https://samples.jblearning.com/9781284211108/9781284211108_FLYR_Mang4eTG.pdf"},{"title":"Health Canada — Eat whole grain foods (Canadian label context)","url":"https://www.canada.ca/en/health-canada/services/food-guide/explore/healthy-eating-recommendations/eat-variety/eat-whole-grains.html"},{"title":"University of Sydney — Glycemic index and load FAQs","url":"https://glycemicindex.com/faqs/"},{"title":"WCRF — Wholegrains, vegetables, fruit and beans","url":"https://www.wcrf.org/research-policy/evidence-for-our-recommendations/wholegrains-veg-fruit-beans/"}]); l.modules[0].moments[0].teaching.unshift(l.sourceCoverage); l.modules.find(m=>m.id==="claims").moments.find(m=>m.id==="vn4-m8").teaching.push("Source-key caution: the inspected third edition, printed page 238 (PDF 251), describes detoxification/elimination as a primary P450 responsibility and also warns of carcinogen activation. That does not justify confidently marking the original True/False item False. Q11 remains source-dependent and unscored until the actual course key is supplied.");})();

(function(){const m=window.VN_LEARNING["lesson-4"].modules.find(m=>m.id==="reading-application").moments; const points=["Distinguish inspected chapters from topic-matched support.","Fruit sugars and refined starch illustrate why food context matters.","Increase fibre gradually and include adequate fluid.","No individual pigment guarantees disease protection.","GI and GL do not measure overall food quality."];m.forEach((x,i)=>x.keyPoints.push(points[i]));m[4].visual.items.push({label:"Real meal",detail:"Preparation, pairing and individual response still matter."});})();

(function(){const m=window.VN_LEARNING["lesson-4"].modules.find(m=>m.id==="reading-application").moments;["Use the title page, not the PDF filename, to identify an edition.","A single food may contain sugars, starch and fibre together.","Fibre tolerance varies; a gradual change is often easier than a sudden jump.","Dark-green leaves can contain carotenoids even when chlorophyll masks their colour.","The numbers here are hypothetical teaching values, not a measured food entry."].forEach((x,i)=>m[i].goodToKnow=x);})();
